import random
import time
import functools

def retry(
    max_attempts=5,
    base_delay=0.5,
    factor=2.0,
    max_delay=30.0,
    jitter=True,
    retryable=(ConnectionError, TimeoutError),
):
    def decorator(fn):
        @functools.wraps(fn)
        def wrapper(*args, **kwargs):
            attempt = 0
            while True:
                try:
                    return fn(*args, **kwargs)
                except retryable as exc:
                    attempt += 1
                    if attempt >= max_attempts:
                        raise
                    delay = min(base_delay * (factor ** (attempt - 1)), max_delay)
                    if jitter:
                        delay = random.uniform(0, delay)
                    time.sleep(delay)
        return wrapper
    return decorator


@retry(max_attempts=4, base_delay=0.2, retryable=(ConnectionError, TimeoutError))
def fetch_partition(path):
    return _read_from_source(path)  # may raise ConnectionError/TimeoutError

