from dataclasses import dataclass
from datetime import datetime, timezone

@dataclass
class FreshnessResult:
    severity: str            # "ok" | "warning" | "page"
    stale_seconds: float
    should_page: bool
    message: str

def check_freshness(last_update, max_staleness_seconds, now=None):
    now = now or datetime.now(timezone.utc)
    if last_update is None:
        return FreshnessResult("page", float("inf"), True,
                               "No successful update recorded")
    if last_update.tzinfo is None:
        last_update = last_update.replace(tzinfo=timezone.utc)

    stale = (now - last_update).total_seconds()
    if stale < 0:  # future timestamp -> clock skew
        return FreshnessResult("warning", stale, False,
                               "Last update is in the future (clock skew?)")

    ratio = stale / max_staleness_seconds
    if ratio <= 1.0:
        return FreshnessResult("ok", stale, False,
                               f"Fresh: {stale:.0f}s within {max_staleness_seconds:.0f}s SLO")
    if ratio <= 2.0:
        return FreshnessResult("warning", stale, False,
                               f"Stale {stale:.0f}s ({ratio:.1f}x SLO)")
    return FreshnessResult("page", stale, True,
                           f"Critically stale {stale:.0f}s ({ratio:.1f}x SLO)")

